async getRelatorio(restaurantId: number, de: string, ate: string) {
  const { data: orders, error } = await this.supabase.client
    .from('orders')
    .select('id, total, status, payment_method, canal, created_at, customer_id, gorjeta_valor, customers(name)')
    .eq('restaurant_id', restaurantId)
    .gte('created_at', de)
    .lte('created_at', ate)
    .order('created_at', { ascending: false });

  if (error) throw error;

  const { data: repassesPeriodo } = await this.supabase.client
    .from('garcom_repasses')
    .select('valor_gorjeta, valor_comissao')
    .eq('restaurant_id', restaurantId)
    .gte('pago_em', de)
    .lte('pago_em', ate);
  const total_gorjetas_pagas = (repassesPeriodo ?? []).reduce((s: number, r: any) => s + (r.valor_gorjeta ?? 0), 0);
  const total_comissoes_pagas = (repassesPeriodo ?? []).reduce((s: number, r: any) => s + (r.valor_comissao ?? 0), 0);

  const orderIds = (orders ?? []).map((o: any) => o.id);

  if (orderIds.length === 0) {
    const { data: caixasVazio } = await this.supabase.client
      .from('caixas').select('id, saidas').eq('restaurant_id', restaurantId)
      .lte('aberto_em', ate).or(`fechado_em.is.null,fechado_em.gte.${de}`);
    const deD = new Date(de); const ateD = new Date(ate);
    const saidasVazio: any[] = [];
    for (const c of (caixasVazio ?? [])) {
      for (const s of (c.saidas ?? [])) {
        const d = new Date(s.criado_em);
        if (d >= deD && d <= ateD) saidasVazio.push(s);
      }
    }
    const totalSaidasVazio = saidasVazio.reduce((sum, s) => sum + (s.valor ?? 0), 0);
    return {
      pedidos: [],
      saidas: saidasVazio,
      fluxo_caixa: [],
      resumo: { total_pedidos: 0, entregues: 0, cancelados: 0, em_andamento: 0, total_vendas: 0, ticket_medio: 0, por_pagamento: {}, total_saidas: totalSaidasVazio, total_comissao: 0, total_gorjeta: 0, total_gorjetas_pagas, total_comissoes_pagas, total_troco: 0, saldo_liquido: -totalSaidasVazio },
    };
  }

  const { data: allItems } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, product_id, quantity, unit_price')
    .in('order_id', orderIds);

  const productIds = [...new Set<number>((allItems ?? []).map((i: any) => i.product_id))];
  const { data: allProds } = productIds.length > 0
    ? await this.supabase.client.from('products').select('id, name').in('id', productIds)
    : { data: [] };

  const prodMap = Object.fromEntries((allProds ?? []).map((p: any) => [p.id, p.name]));
  const itemsByOrder = (allItems ?? []).reduce((acc: any, item: any) => {
    if (!acc[item.order_id]) acc[item.order_id] = [];
    acc[item.order_id].push({ ...item, product_name: prodMap[item.product_id] ?? `#${item.product_id}` });
    return acc;
  }, {});

  const pedidos = (orders ?? []).map((o: any) => ({ ...o, itens: itemsByOrder[o.id] ?? [] }));

  const entregues = pedidos.filter((p: any) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
  const cancelados = pedidos.filter((p: any) => p.status === 'canceled');
  const em_andamento = pedidos.filter((p: any) => !['canceled', 'delivered', 'paga'].includes(p.status));
  const nao_cancelados = pedidos.filter((p: any) => p.status !== 'canceled');
  const total_vendas = entregues.reduce((s: number, p: any) => s + (p.total ?? 0), 0);
  const pagamentosPorComandaRelatorio = await this.buscarPagamentosPorComanda(nao_cancelados);
  const por_pagamento = nao_cancelados.reduce((acc: any, p: any) => {
    const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComandaRelatorio.get(p.id) : undefined;
    if (pagamentosComanda?.length) {
      for (const pag of pagamentosComanda) {
        const m = pag.forma_pagamento ?? 'unknown';
        if (!acc[m]) acc[m] = { count: 0, total: 0 };
        acc[m].count++;
        acc[m].total += pag.valor ?? 0;
        const taxa = pag.taxa_cartao_valor ?? 0;
        if (taxa > 0) {
          if (!acc['taxa_cartao']) acc['taxa_cartao'] = { count: 0, total: 0 };
          acc['taxa_cartao'].count++;
          acc['taxa_cartao'].total += taxa;
        }
      }
      return acc;
    }
    const m = p.payment_method ?? 'unknown';
    if (!acc[m]) acc[m] = { count: 0, total: 0 };
    acc[m].count++;
    acc[m].total += p.total ?? 0;
    return acc;
  }, {} as Record<string, { count: number; total: number }>);

  // Saídas de caixas que se sobrepõem ao período
  const { data: caixasPeriodo } = await this.supabase.client
    .from('caixas')
    .select('id, saidas')
    .eq('restaurant_id', restaurantId)
    .lte('aberto_em', ate)
    .or(`fechado_em.is.null,fechado_em.gte.${de}`);

  const deDate = new Date(de);
  const ateDate = new Date(ate);
  const saidas: any[] = [];
  for (const c of (caixasPeriodo ?? [])) {
    for (const s of (c.saidas ?? [])) {
      const d = new Date(s.criado_em);
      if (d >= deDate && d <= ateDate) saidas.push(s);
    }
  }
  const total_saidas = saidas.reduce((sum, s) => sum + (s.valor ?? 0), 0);

  // Comissão paga aos garçons no período (lançada no fechamento de cada comanda).
  const { data: comissoesPeriodo } = orderIds.length
    ? await this.supabase.client
        .from('garcom_comissoes_lancamentos')
        .select('valor_calculado')
        .in('order_id', orderIds)
    : { data: [] as any[] };
  const total_comissao = (comissoesPeriodo ?? []).reduce((s: number, c: any) => s + (c.valor_calculado ?? 0), 0);

  const total_gorjeta = entregues.reduce((s: number, p: any) => s + (p.gorjeta_valor ?? 0), 0);

  // Fluxo de caixa detalhado: cada pagamento individual, discriminado por forma e origem
  // (garçom/estabelecimento pra comanda, delivery pra pedido de entrega).
  const fluxo_caixa: any[] = [];
  let total_troco = 0;
  for (const p of nao_cancelados) {
    const pagamentosComanda = p.canal === 'presencial' ? pagamentosPorComandaRelatorio.get(p.id) : undefined;
    if (pagamentosComanda?.length) {
      for (const pag of pagamentosComanda) {
        fluxo_caixa.push({ order_id: p.id, forma_pagamento: pag.forma_pagamento, origem: pag.origem, valor: pag.valor, troco: pag.troco, criado_em: pag.criado_em });
        total_troco += pag.troco ?? 0;
      }
    } else {
      fluxo_caixa.push({ order_id: p.id, forma_pagamento: p.payment_method ?? 'unknown', origem: 'delivery', valor: p.total ?? 0, troco: 0, criado_em: p.created_at });
    }
  }
  fluxo_caixa.sort((a, b) => new Date(a.criado_em).getTime() - new Date(b.criado_em).getTime());

  return {
    pedidos,
    saidas,
    fluxo_caixa,
    resumo: {
      total_pedidos: pedidos.length,
      entregues: entregues.length,
      cancelados: cancelados.length,
      em_andamento: em_andamento.length,
      total_vendas,
      ticket_medio: entregues.length > 0 ? total_vendas / entregues.length : 0,
      por_pagamento,
      total_saidas,
      total_comissao,
      total_gorjeta,
      total_gorjetas_pagas,
      total_comissoes_pagas,
      total_troco,
      saldo_liquido: total_vendas - total_saidas,
    },
  };
}

// Relatório Garçom: total vendido/comissão/gorjeta são recortados pelo período (de/ate);
// comandas abertas/pendentes são estado atual (live), não faz sentido filtrar por data
// já que uma comanda aberta hoje pode ter sido criada ontem.
async getRelatorioGarcom(restaurantId: number, de: string, ate: string) {
  const { data: garcons } = await this.supabase.client
    .from('garcons')
    .select('id, nome')
    .eq('restaurant_id', restaurantId);

