content.content:
1	import React, { useState } from 'react';
2	import Icon from '../../components/AppIcon';
3	import { adicionarSaida, adicionarEntrada, estornarSaida, fecharCaixa } from '../../services/restauranteService';
4	import FecharCaixaModal from '../restaurante-dashboard/FecharCaixaModal';
5	
6	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
7	const fmtHora = (d) => d ? new Date(d).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : '—';
8	const MEIO_LABELS = { dinheiro: 'Dinheiro', pix: 'PIX', transferencia: 'Transferência', cartao: 'Cartão' };
9	const PL = { cash: 'Dinheiro', pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito' };
10	
11	const Kpi = ({ icon, label, value, sub, color = 'gray' }) => {
12	  const colors = {
13	    green: 'border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-950/40',
14	    blue:  'border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/40',
15	    amber: 'border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/40',
16	    red:   'border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-950/40',
17	    gray:  'border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#27272A]',
18	  };
19	  const txt = { green: 'text-green-700 dark:text-green-400', blue: 'text-blue-700 dark:text-blue-400', amber: 'text-amber-700 dark:text-amber-400', red: 'text-red-600 dark:text-red-400', gray: 'text-[#18181B] dark:text-[#F4F4F5]' };
20	  return (
21	    <div className={`rounded-xl border p-3 ${colors[color]}`}>
22	      <div className="flex items-center gap-1.5 mb-1">
23	        <Icon name={icon} size={13} className={txt[color]} />
24	        <p className="text-[10px] font-bold uppercase tracking-widest text-[#71717A] dark:text-[#A1A1AA]">{label}</p>
25	      </div>
26	      <p className={`text-xl font-black ${txt[color]}`}>{value}</p>
27	      {sub && <p className="text-[10px] text-[#71717A] dark:text-[#A1A1AA] mt-0.5">{sub}</p>}
28	    </div>
29	  );
30	};
31	
32	// Modal de sangria ou adição
33	const MovimentoModal = ({ tipo, onSalvar, onCancelar, salvando }) => {
34	  const [descricao, setDescricao] = useState('');
35	  const [valor, setValor] = useState('');
36	  const [meio, setMeio] = useState('dinheiro');
37	  const isSaida = tipo === 'sangria';
38	
39	  return (
40	    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
41	      <div className="bg-white dark:bg-[#27272A] rounded-2xl p-6 w-full max-w-sm shadow-2xl">
42	        <div className="text-center mb-4">
43	          <p className="text-2xl mb-1">{isSaida ? '💸' : '💰'}</p>
44	          <h2 className="text-base font-bold text-[#18181B] dark:text-[#F4F4F5]">{isSaida ? 'Sangria (Retirada)' : 'Adição de Dinheiro'}</h2>
45	          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">{isSaida ? 'Retirada de dinheiro do caixa com motivo' : 'Entrada de dinheiro no caixa'}</p>
46	        </div>
47	        <div className="space-y-3 mb-4">
48	          <div>
49	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">
50	              {isSaida ? 'Motivo da retirada *' : 'Descrição *'}
51	            </label>
52	            <input value={descricao} onChange={(e) => setDescricao(e.target.value)}
53	              placeholder={isSaida ? 'Ex: Pagamento fornecedor, troco extra…' : 'Ex: Reforço de troco, fundo extra…'}
54	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
55	          </div>
56	          <div>
57	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Valor (R$) *</label>
58	            <input type="number" min="0.01" step="0.01" value={valor} onChange={(e) => setValor(e.target.value)}
59	              placeholder="0,00"
60	              className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
61	          </div>
62	          <div>
63	            <label className="block text-xs font-semibold text-[#71717A] dark:text-[#A1A1AA] mb-1">Meio</label>
64	            <select value={meio} onChange={(e) => setMeio(e.target.value)}
65	              className="mx-2 sm:mx-0 w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]">
66	              <option value="dinheiro">Dinheiro</option>
67	              <option value="pix">PIX</option>
68	              <option value="transferencia">Transferência</option>
69	              <option value="cartao">Cartão</option>
70	            </select>
71	          </div>
72	        </div>
73	        <div className="flex gap-2">
74	          <button onClick={onCancelar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] dark:border-[#3F3F46] rounded-xl text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#3F3F46]">Cancelar</button>
75	          <button
76	            onClick={() => onSalvar({ descricao: descricao.trim(), valor: parseFloat(valor) || 0, meio })}
77	            disabled={salvando || !descricao.trim() || !parseFloat(valor)}
78	            className={`flex-1 py-2.5 text-sm rounded-xl font-bold text-white disabled:opacity-50 ${isSaida ? 'bg-red-500 hover:bg-red-600' : 'bg-green-600 hover:bg-green-700'}`}>
79	            {salvando ? 'Salvando...' : isSaida ? 'Registrar Sangria' : 'Registrar Adição'}
80	          </button>
81	        </div>
82	      </div>
83	    </div>
84	  );
85	};
86	
87	const CaixaAtualPanel = ({ caixa, taxaPagbank, onRefresh, pedidosAbertos = [] }) => {
88	  const [modal, setModal] = useState(null); // 'sangria' | 'adicao' | 'fechar' | null
89	  const [salvando, setSalvando] = useState(false);
90	  const [fechando, setFechando] = useState(false);
91	  const [estornando, setEstornando] = useState(null); // index da saída sendo estornada
92	  const [pendencias, setPendencias] = useState(null); // { pedidos, comandas, mesas } vindo do 409 do backend
93	
94	  if (!caixa?.aberto) return null;
95	
96	  const r = caixa.resumo ?? {};
97	  const por = r.por_pagamento ?? {};
98	  const digitalTotal = Object.entries(por).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v, 0);
99	  const taxaEst = taxaPagbank > 0 ? digitalTotal * (taxaPagbank / 100) : 0;
100	  const saidas = caixa.saidas ?? [];
101	  const entradas = caixa.entradas ?? [];
102	
103	  const handleMovimento = async (body) => {
104	    setSalvando(true);
105	    try {
106	      if (modal === 'sangria') await adicionarSaida(body);
107	      else await adicionarEntrada(body);
108	      await onRefresh();
109	      setModal(null);
110	    } catch (e) { alert(e.message); }
111	    finally { setSalvando(false); }
112	  };
113	
114	  const handleEstornar = async (index) => {
115	    if (!confirm('Estornar essa saída? O valor volta a contar no caixa.')) return;
116	    setEstornando(index);
117	    try {
118	      await estornarSaida(index);
119	      await onRefresh();
120	    } catch (e) { alert(e.message); }
121	    finally { setEstornando(null); }
122	  };
123	
124	  const handleFechar = async (body) => {
125	    setFechando(true);
126	    try {
127	      await fecharCaixa(body);
128	      await onRefresh();
129	      setModal(null);
130	      setPendencias(null);
131	    } catch (e) {
132	      if (e.data?.pedidos || e.data?.comandas || e.data?.mesas) {
133	        setPendencias({ pedidos: e.data.pedidos ?? [], comandas: e.data.comandas ?? [], mesas: e.data.mesas ?? [] });
134	      } else {
135	        alert(e.message);
136	      }
137	    }
138	    finally { setFechando(false); }
139	  };
140	
141	  return (
142	    <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-5">
143	      {/* Header */}
144	      <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
145	        <div>
146	          <div className="flex items-center gap-2">
147	            <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
148	            <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">Caixa em Operação</p>
149	          </div>
150	          <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] mt-0.5">
151	            {caixa.nome_operador} · aberto às {fmtHora(caixa.aberto_em)} · fundo: {fmt(caixa.valor_inicial)}
152	          </p>
153	        </div>
154	        <div className="flex flex-wrap gap-2">
155	          <button onClick={() => setModal('sangria')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl hover:bg-red-50 dark:hover:bg-red-950/40">
156	            <Icon name="ArrowDownLeft" size={13} /> Sangria
157	          </button>
158	          <button onClick={() => setModal('adicao')} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-green-200 dark:border-green-800 text-green-700 dark:text-green-400 rounded-xl hover:bg-green-50 dark:hover:bg-green-950/40">
159	            <Icon name="ArrowUpRight" size={13} /> Adição
160	          </button>
161	          <button onClick={() => { setPendencias(null); setModal('fechar'); }} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold bg-red-500 text-white rounded-xl hover:bg-red-600">
162	            <Icon name="Lock" size={13} /> Fechar Caixa
163	          </button>
164	        </div>
165	      </div>
166	
167	      {/* KPIs principais */}
168	      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-3">
169	        <Kpi icon="Banknote"   label="Espécie no caixa" value={fmt(r.especie_calculada)} color="green" sub="Dinheiro físico esperado" />
170	        <Kpi icon="Smartphone" label="Digital (PagBank)" value={fmt(digitalTotal)} color="blue"
171	          sub={taxaEst > 0 ? `Taxa est.: ${fmt(taxaEst)}` : 'Sem taxa configurada'} />
172	        <Kpi icon="TrendingUp" label="Total Vendas" value={fmt(r.total_vendas)} color="gray" sub={`${r.entregues ?? 0} pedidos entregues`} />
173	      </div>
174	
175	      {/* KPIs secundários */}
176	      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-4">
177	        <Kpi icon="Wallet"       label="Fundo Inicial (Troco)" value={fmt(caixa.valor_inicial)} color="gray" />
178	        <Kpi icon="ArrowUpRight" label="Adições"               value={fmt(r.total_entradas)}   color="green" sub={`${entradas.length} registros`} />
179	        <Kpi icon="ArrowDownLeft" label="Sangrias / Saídas"    value={fmt(r.total_saidas)}     color="red"   sub={`${saidas.length} registros`} />
180	      </div>
181	
182	      {/* Vendas por método */}
183	      {Object.keys(por).length > 0 && (
184	        <div className="bg-[#FAFAFA] dark:bg-[#18181B] rounded-xl p-3 mb-3">
185	          <p className="text-[10px] font-black text-[#A1A1AA] uppercase tracking-widest mb-2">Vendas por método de pagamento</p>
186	          <div className="flex flex-wrap gap-3">
187	            {Object.entries(por).map(([k, v]) => (
188	              <div key={k} className="text-sm">
189	                <span className="text-[#71717A] dark:text-[#A1A1AA]">{PL[k] ?? k}: </span>
190	                <span className="font-bold text-[#18181B] dark:text-[#F4F4F5]">{fmt(v)}</span>
191	              </div>
192	            ))}
193	          </div>
