                                </div>
                              ))}
                              {saidas.length === 0 && entradas.length === 0 && <p className="text-xs text-[#71717A] dark:text-[#A1A1AA] text-center py-2">Sem movimentos</p>}
                            </div>
                          </div>
                        </div>
                      );
                    })() : null}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

